urn:table-manners:core:description.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:table-manners:core:description",
  "title": "Description document (CONTRACT.md 3; readiness 3.1; renders 3.2; the images profile's fields, 11.2)",
  "description": "What a tool does, in terms a client needs nothing else to call it by: `<tool> describe --json` and the describe MCP tool.",
  "type": "object",
  "required": [
    "contract",
    "profiles",
    "tool",
    "actions",
    "progress_interval_s",
    "resources"
  ],
  "properties": {
    "contract": {
      "$ref": "urn:table-manners:core:result#/$defs/version"
    },
    "profiles": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "enum": [
          "images"
        ]
      },
      "description": "The profiles the tool implements; [] for a core-only tool."
    },
    "tool": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "version",
        "purpose"
      ],
      "properties": {
        "name": {
          "type": "string",
          "pattern": "^[a-z][a-z0-9-]*$"
        },
        "version": {
          "type": "string",
          "minLength": 1
        },
        "purpose": {
          "type": "string",
          "minLength": 1
        }
      }
    },
    "actions": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "#/$defs/action"
      }
    },
    "vocabulary": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "disposition",
        "confidence",
        "evidence",
        "score_kind"
      ],
      "description": "Images profile: every word the tool emits in a location's disposition, confidence, evidence and score_kind.",
      "properties": {
        "disposition": {
          "$ref": "#/$defs/words"
        },
        "confidence": {
          "$ref": "#/$defs/words"
        },
        "evidence": {
          "$ref": "#/$defs/words"
        },
        "score_kind": {
          "$ref": "#/$defs/words"
        }
      }
    },
    "limits": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "inline_bytes"
      ],
      "properties": {
        "inline_bytes": {
          "type": "integer",
          "minimum": 0
        }
      },
      "description": "Images profile."
    },
    "progress_interval_s": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10,
      "description": "The longest gap between progress notifications on a live run."
    },
    "resources": {
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^[a-z][a-z0-9+.-]*://"
      }
    }
  },
  "patternProperties": {
    "^x-[a-z][a-z0-9-]*$": {}
  },
  "additionalProperties": false,
  "if": {
    "required": [
      "profiles"
    ],
    "properties": {
      "profiles": {
        "contains": {
          "const": "images"
        }
      }
    }
  },
  "then": {
    "required": [
      "vocabulary",
      "limits"
    ],
    "properties": {
      "actions": {
        "items": {
          "required": [
            "images",
            "locations",
            "outputs"
          ]
        }
      }
    }
  },
  "else": {
    "properties": {
      "vocabulary": false,
      "limits": false,
      "actions": {
        "items": {
          "properties": {
            "images": false,
            "locations": false,
            "outputs": false
          }
        }
      }
    }
  },
  "$defs": {
    "words": {
      "type": "array",
      "uniqueItems": true,
      "items": {
        "type": "string",
        "pattern": "^[a-z0-9][a-z0-9_-]*$"
      }
    },
    "action": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "title",
        "purpose",
        "params_schema",
        "cost",
        "readiness",
        "duration",
        "renders"
      ],
      "properties": {
        "name": {
          "allOf": [
            {
              "$ref": "urn:table-manners:core:result#/$defs/action_name"
            },
            {
              "not": {
                "enum": [
                  "describe",
                  "estimate"
                ]
              }
            }
          ],
          "description": "The MCP tool name; describe and estimate are reserved (CONTRACT.md 5)."
        },
        "title": {
          "type": "string",
          "minLength": 1
        },
        "purpose": {
          "type": "string",
          "minLength": 1
        },
        "images": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "slot",
              "role",
              "required"
            ],
            "properties": {
              "slot": {
                "type": "string",
                "pattern": "^[a-z][a-z0-9_]*$"
              },
              "role": {
                "type": "string",
                "pattern": "^[a-z0-9][a-z0-9_-]*$"
              },
              "required": {
                "type": "boolean"
              },
              "many": {
                "type": "boolean",
                "description": "The slot takes a non-empty list of images (CONTRACT.md 10.1); false when absent."
              }
            }
          },
          "description": "Images profile."
        },
        "locations": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "slot",
              "kinds",
              "required"
            ],
            "properties": {
              "slot": {
                "type": "string",
                "pattern": "^[a-z][a-z0-9_]*$"
              },
              "kinds": {
                "type": "array",
                "minItems": 1,
                "uniqueItems": true,
                "items": {
                  "enum": [
                    "bbox",
                    "polygon",
                    "line",
                    "stroke",
                    "mask",
                    "whole_image",
                    "absent",
                    "view"
                  ]
                }
              },
              "required": {
                "type": "boolean"
              }
            }
          },
          "description": "Images profile."
        },
        "params_schema": {
          "type": "object",
          "description": "A JSON Schema for the action's other arguments."
        },
        "outputs": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "images",
            "locations"
          ],
          "properties": {
            "images": {
              "$ref": "#/$defs/words",
              "description": "The roles of the images the action returns."
            },
            "locations": {
              "type": "array",
              "uniqueItems": true,
              "items": {
                "enum": [
                  "found"
                ]
              }
            }
          },
          "description": "Images profile."
        },
        "cost": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "may_spend"
          ],
          "properties": {
            "may_spend": {
              "type": "boolean"
            },
            "basis": {
              "enum": [
                "measured",
                "estimated"
              ]
            }
          },
          "if": {
            "properties": {
              "may_spend": {
                "const": true
              }
            }
          },
          "then": {
            "required": [
              "basis"
            ]
          }
        },
        "readiness": {
          "$ref": "#/$defs/readiness"
        },
        "duration": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "typical_s",
            "max_s"
          ],
          "properties": {
            "typical_s": {
              "type": "number",
              "minimum": 0
            },
            "max_s": {
              "type": "number",
              "exclusiveMinimum": 0
            }
          }
        },
        "renders": {
          "type": "array",
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": [
              "name",
              "kind",
              "command"
            ],
            "properties": {
              "name": {
                "type": "string",
                "pattern": "^[a-z][a-z0-9_-]*$"
              },
              "kind": {
                "enum": [
                  "document",
                  "server"
                ],
                "description": "document: writes a file and prints its absolute path; server: prints its URL once listening and serves until stdin closes or SIGTERM (CONTRACT.md 3.2)."
              },
              "ready_timeout_s": {
                "type": "integer",
                "minimum": 1,
                "maximum": 60,
                "description": "Server renders: the longest wait for the URL line."
              },
              "command": {
                "type": "array",
                "minItems": 1,
                "items": {
                  "type": "string"
                }
              }
            },
            "if": {
              "properties": {
                "kind": {
                  "const": "server"
                }
              }
            },
            "then": {
              "required": [
                "ready_timeout_s"
              ]
            },
            "else": {
              "properties": {
                "ready_timeout_s": false
              }
            }
          }
        }
      },
      "if": {
        "properties": {
          "cost": {
            "properties": {
              "may_spend": {
                "const": true
              }
            }
          }
        }
      },
      "then": {
        "properties": {
          "params_schema": {
            "required": [
              "properties"
            ],
            "properties": {
              "properties": {
                "required": [
                  "max_spend_usd"
                ],
                "properties": {
                  "max_spend_usd": {
                    "required": [
                      "type",
                      "exclusiveMinimum"
                    ],
                    "properties": {
                      "type": {
                        "const": "number"
                      },
                      "exclusiveMinimum": {
                        "const": 0
                      }
                    }
                  }
                }
              }
            }
          }
        },
        "description": "An action that may spend declares max_spend_usd, a number above zero, so a host can always pass its cap (CONTRACT.md 4.5)."
      }
    },
    "readiness": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "state",
        "requirements"
      ],
      "description": "Whether the action can run here, now, and what stands in the way (CONTRACT.md 3.1). Never a credential value.",
      "properties": {
        "state": {
          "enum": [
            "ready",
            "needs_setup",
            "unavailable"
          ]
        },
        "requirements": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/requirement"
          }
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "state": {
                "const": "ready"
              }
            }
          },
          "then": {
            "properties": {
              "requirements": {
                "items": {
                  "properties": {
                    "state": {
                      "not": {
                        "enum": [
                          "missing",
                          "invalid"
                        ]
                      }
                    }
                  }
                }
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "state": {
                "const": "needs_setup"
              }
            }
          },
          "then": {
            "properties": {
              "requirements": {
                "contains": {
                  "properties": {
                    "state": {
                      "enum": [
                        "missing",
                        "invalid"
                      ]
                    }
                  },
                  "required": [
                    "state"
                  ]
                }
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "state": {
                "const": "unavailable"
              }
            }
          },
          "then": {
            "properties": {
              "requirements": {
                "minItems": 1
              }
            }
          }
        }
      ]
    },
    "requirement": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "kind",
        "name",
        "state"
      ],
      "properties": {
        "kind": {
          "enum": [
            "config",
            "credential",
            "env",
            "model",
            "file",
            "dependency"
          ]
        },
        "name": {
          "type": "string",
          "minLength": 1,
          "maxLength": 256
        },
        "state": {
          "enum": [
            "missing",
            "present",
            "valid",
            "invalid",
            "unknown"
          ]
        },
        "setup": {
          "type": "string",
          "minLength": 1,
          "description": "A sentence a person can act on."
        }
      }
    }
  }
}

urn:table-manners:core:estimate.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:table-manners:core:estimate",
  "title": "Estimate (CONTRACT.md 4.5)",
  "description": "What the reserved estimate tool returns as structuredContent: the worst case of one exact call, bound to its inputs, configuration, tool version and session. Never a run.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "contract",
    "tool",
    "action",
    "binding",
    "session_id",
    "effective",
    "worst_case_usd",
    "cap_usd",
    "allowed",
    "refused",
    "readiness",
    "session",
    "expires"
  ],
  "properties": {
    "contract": {
      "$ref": "urn:table-manners:core:result#/$defs/version"
    },
    "tool": {
      "$ref": "urn:table-manners:core:result#/$defs/tool"
    },
    "action": {
      "allOf": [
        {
          "$ref": "urn:table-manners:core:result#/$defs/action_name"
        },
        {
          "not": {
            "enum": [
              "describe",
              "estimate"
            ]
          }
        }
      ],
      "description": "The paid action priced."
    },
    "binding": {
      "type": "string",
      "pattern": "^sha256:[0-9a-f]{64}$",
      "description": "Sent back as _meta[\"table-manners/estimate\"] on the paid call."
    },
    "session_id": {
      "oneOf": [
        {
          "type": "null"
        },
        {
          "$ref": "urn:table-manners:core:run-ref#/$defs/session_id"
        }
      ],
      "description": "Null for an estimate from the command line, which no server accepts."
    },
    "effective": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "model",
        "config_identity"
      ],
      "properties": {
        "model": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1
        },
        "config_identity": {
          "oneOf": [
            {
              "type": "null"
            },
            {
              "type": "string",
              "pattern": "^sha256:[0-9a-f]{64}$"
            }
          ],
          "description": "Null only when there is no configuration."
        }
      },
      "patternProperties": {
        "^x-[a-z][a-z0-9-]*$": {}
      }
    },
    "worst_case_usd": {
      "oneOf": [
        {
          "type": "null"
        },
        {
          "$ref": "#/$defs/usd"
        }
      ],
      "description": "What the limits check would reserve; null only when the call cannot be priced (refused for readiness), never a made-up zero."
    },
    "cap_usd": {
      "oneOf": [
        {
          "type": "null"
        },
        {
          "$ref": "#/$defs/usd"
        }
      ],
      "description": "The effective per-call cap; null when uncapped, never zero allowance."
    },
    "allowed": {
      "type": "boolean"
    },
    "refused": {
      "enum": [
        null,
        "cap",
        "budget",
        "readiness"
      ]
    },
    "readiness": {
      "$ref": "urn:table-manners:core:description#/$defs/readiness"
    },
    "session": {
      "oneOf": [
        {
          "type": "null"
        },
        {
          "$ref": "urn:table-manners:core:session"
        }
      ]
    },
    "expires": {
      "type": "string",
      "format": "date-time",
      "description": "When the tool stops honouring the binding; at most 24 hours after the estimate."
    }
  },
  "if": {
    "properties": {
      "allowed": {
        "const": true
      }
    }
  },
  "then": {
    "properties": {
      "refused": {
        "const": null
      }
    }
  },
  "else": {
    "properties": {
      "refused": {
        "enum": [
          "cap",
          "budget",
          "readiness"
        ]
      }
    }
  },
  "$defs": {
    "usd": {
      "type": "number",
      "minimum": 0
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "session_id": {
            "type": "null"
          }
        }
      },
      "then": {
        "properties": {
          "session": {
            "type": "null"
          }
        }
      },
      "else": {
        "properties": {
          "session": {
            "type": "object"
          }
        }
      }
    },
    {
      "if": {
        "not": {
          "properties": {
            "refused": {
              "const": "readiness"
            }
          }
        }
      },
      "then": {
        "properties": {
          "worst_case_usd": {
            "type": "number"
          },
          "effective": {
            "properties": {
              "config_identity": {
                "type": "string"
              }
            }
          }
        }
      }
    }
  ]
}

urn:table-manners:core:refusal.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:table-manners:core:refusal",
  "title": "Refusal data (CONTRACT.md 3.1, 4.4, 4.5)",
  "description": "The `data` of a JSON-RPC -32602 error the contract names, so a host can tell it from other invalid params.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "reason",
    "run"
  ],
  "properties": {
    "reason": {
      "enum": [
        "client_run_id_reused",
        "not_ready",
        "invalid_arguments"
      ]
    },
    "run": {
      "oneOf": [
        {
          "type": "null"
        },
        {
          "$ref": "urn:table-manners:core:run-ref"
        }
      ],
      "description": "client_run_id_reused: the earlier request's run, null while it has none (queued, or cancelled before allocation). not_ready: always null."
    },
    "requirements": {
      "type": "array",
      "minItems": 1,
      "items": {
        "$ref": "urn:table-manners:core:description#/$defs/requirement"
      },
      "description": "not_ready: the requirements this call needs that are missing or invalid."
    },
    "error": {
      "$ref": "urn:table-manners:core:result#/$defs/error_object",
      "description": "invalid_arguments: what was wrong, as in a result (code usage or input, not retryable)."
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "reason": {
            "const": "not_ready"
          }
        }
      },
      "then": {
        "required": [
          "requirements"
        ],
        "properties": {
          "run": {
            "type": "null"
          }
        }
      },
      "else": {
        "properties": {
          "requirements": false
        }
      }
    },
    {
      "if": {
        "properties": {
          "reason": {
            "const": "invalid_arguments"
          }
        }
      },
      "then": {
        "required": [
          "error"
        ],
        "properties": {
          "run": {
            "type": "null"
          },
          "error": {
            "properties": {
              "code": {
                "enum": [
                  "usage",
                  "input"
                ]
              },
              "retryable": {
                "const": false
              }
            }
          }
        }
      },
      "else": {
        "properties": {
          "error": false
        }
      }
    }
  ]
}

urn:table-manners:core:result.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:table-manners:core:result",
  "title": "Result (CONTRACT.md 2; the images profile's fields, 11.1)",
  "description": "One shape everywhere: the MCP result's structuredContent, the run resource and run.json. The header is the contract's; body is the tool's.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "contract",
    "tool",
    "action",
    "run",
    "status",
    "error",
    "started",
    "finished",
    "duration_ms",
    "input_identity",
    "spend",
    "cache",
    "notes",
    "body"
  ],
  "properties": {
    "contract": {
      "$ref": "#/$defs/version"
    },
    "tool": {
      "$ref": "#/$defs/tool"
    },
    "action": {
      "$ref": "#/$defs/action_name"
    },
    "run": {
      "$ref": "urn:table-manners:core:run-ref#/$defs/run_ref",
      "required": [
        "dir"
      ],
      "properties": {
        "dir": {
          "type": [
            "string",
            "null"
          ],
          "description": "The run directory on a local transport, else null."
        }
      },
      "unevaluatedProperties": false
    },
    "status": {
      "enum": [
        "completed",
        "cancelled",
        "error",
        "invalid"
      ]
    },
    "error": {
      "oneOf": [
        {
          "type": "null"
        },
        {
          "$ref": "#/$defs/error_object"
        }
      ]
    },
    "started": {
      "type": "string",
      "format": "date-time"
    },
    "finished": {
      "type": "string",
      "format": "date-time"
    },
    "duration_ms": {
      "type": "integer",
      "minimum": 0
    },
    "input_identity": {
      "type": "string",
      "pattern": "^sha256:[0-9a-f]{64}$"
    },
    "spend": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "usd",
        "unresolved_usd",
        "basis"
      ],
      "properties": {
        "usd": {
          "type": "number",
          "minimum": 0
        },
        "unresolved_usd": {
          "type": "number",
          "minimum": 0,
          "description": "The part of usd no provider answer settled (4.5): an upper bound, not a charge."
        },
        "basis": {
          "enum": [
            "measured",
            "estimated"
          ]
        }
      }
    },
    "cache": {
      "enum": [
        "hit",
        "miss",
        "off"
      ]
    },
    "images": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "in",
        "out"
      ],
      "properties": {
        "in": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/image_taken"
          }
        },
        "out": {
          "type": "array",
          "items": {
            "$ref": "urn:table-manners:images:image-out"
          }
        }
      },
      "description": "Images profile: required in every result of an images tool."
    },
    "locations": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "used",
        "found"
      ],
      "properties": {
        "used": {
          "type": "array",
          "items": {
            "$ref": "urn:table-manners:images:location"
          }
        },
        "found": {
          "type": "array",
          "items": {
            "$ref": "urn:table-manners:images:location"
          }
        }
      },
      "description": "Images profile: required in every result of an images tool."
    },
    "notes": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "body": {
      "type": "object",
      "description": "The tool's own."
    }
  },
  "if": {
    "properties": {
      "status": {
        "enum": [
          "error",
          "invalid"
        ]
      }
    }
  },
  "then": {
    "properties": {
      "error": {
        "type": "object"
      }
    }
  },
  "else": {
    "properties": {
      "error": {
        "type": "null"
      }
    }
  },
  "$defs": {
    "version": {
      "type": "string",
      "pattern": "^(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)\\.(0|[1-9][0-9]*)$"
    },
    "tool": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "name",
        "version"
      ],
      "properties": {
        "name": {
          "type": "string",
          "pattern": "^[a-z][a-z0-9-]*$"
        },
        "version": {
          "type": "string",
          "minLength": 1
        }
      }
    },
    "action_name": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9_]*$"
    },
    "image_taken": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "slot",
        "role",
        "image"
      ],
      "description": "Images profile: an image the run took in: the slot it came through, its role and its reference.",
      "properties": {
        "slot": {
          "type": "string",
          "minLength": 1
        },
        "role": {
          "type": "string",
          "pattern": "^[a-z0-9][a-z0-9_-]*$"
        },
        "image": {
          "$ref": "urn:table-manners:images:image-reference"
        }
      }
    },
    "error_object": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "code",
        "retryable",
        "reason"
      ],
      "properties": {
        "code": {
          "enum": [
            "usage",
            "input",
            "stale_estimate",
            "io",
            "provider",
            "credential",
            "cap",
            "budget",
            "timeout",
            "tool_process",
            "internal"
          ]
        },
        "retryable": {
          "type": "boolean"
        },
        "reason": {
          "type": "string",
          "minLength": 1
        }
      },
      "if": {
        "properties": {
          "code": {
            "enum": [
              "stale_estimate",
              "credential",
              "cap",
              "budget"
            ]
          }
        }
      },
      "then": {
        "properties": {
          "retryable": {
            "const": false
          }
        }
      }
    }
  }
}

urn:table-manners:core:run-ref.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:table-manners:core:run-ref",
  "title": "Run reference (CONTRACT.md 4.3)",
  "description": "A run's identity, the same wherever it appears: progress _meta (`table-manners/run`), the result's run (with `dir`), runs-list entries and a reuse refusal. The root is closed; the other schemas extend $defs/run_ref and close it themselves.",
  "$ref": "#/$defs/run_ref",
  "unevaluatedProperties": false,
  "$defs": {
    "run_ref": {
      "type": "object",
      "required": [
        "id",
        "resource",
        "session_id",
        "client_run_id"
      ],
      "properties": {
        "id": {
          "type": "string",
          "minLength": 1,
          "description": "Unique per tool."
        },
        "resource": {
          "type": "string",
          "pattern": "^[a-z][a-z0-9+.-]*://run/",
          "description": "<tool>://run/<id>/run.json"
        },
        "session_id": {
          "oneOf": [
            {
              "type": "null"
            },
            {
              "$ref": "#/$defs/session_id"
            }
          ],
          "description": "The serving session; null for a run made outside one (a tool's CLI)."
        },
        "client_run_id": {
          "oneOf": [
            {
              "type": "null"
            },
            {
              "$ref": "#/$defs/client_run_id"
            }
          ],
          "description": "The caller's correlation id; null when the request sent none."
        }
      }
    },
    "session_id": {
      "type": "string",
      "pattern": "^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$",
      "description": "A random UUID (v4), lowercase, generated when the server starts."
    },
    "client_run_id": {
      "type": "string",
      "pattern": "^[A-Za-z0-9._:-]{1,128}$"
    }
  }
}

urn:table-manners:core:runs.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:table-manners:core:runs",
  "title": "Runs list (CONTRACT.md 4.3)",
  "description": "The `<tool>://runs{?cursor}` resource: one page of runs, newest first, so a run is discoverable without its id.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "contract",
    "tool",
    "runs",
    "next_cursor"
  ],
  "properties": {
    "contract": {
      "$ref": "urn:table-manners:core:result#/$defs/version"
    },
    "tool": {
      "$ref": "urn:table-manners:core:result#/$defs/tool"
    },
    "runs": {
      "type": "array",
      "items": {
        "$ref": "urn:table-manners:core:run-ref#/$defs/run_ref",
        "required": [
          "action",
          "status",
          "started"
        ],
        "properties": {
          "action": {
            "$ref": "urn:table-manners:core:result#/$defs/action_name"
          },
          "status": {
            "enum": [
              "running",
              "completed",
              "cancelled",
              "error",
              "invalid"
            ]
          },
          "started": {
            "type": "string",
            "format": "date-time"
          }
        },
        "unevaluatedProperties": false
      }
    },
    "next_cursor": {
      "type": [
        "string",
        "null"
      ],
      "pattern": "^[A-Za-z0-9._~-]{1,256}$",
      "description": "Opaque, URI-unreserved characters only, so it goes into <tool>://runs?cursor=<next_cursor> unencoded. Null on the last page."
    }
  }
}

urn:table-manners:core:session.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:table-manners:core:session",
  "title": "Session (CONTRACT.md 4.6)",
  "description": "The `<tool>://session` resource: one atomic observation of the serving process's spend ledger.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "contract",
    "tool",
    "id",
    "started",
    "budget_usd",
    "spent_usd",
    "unresolved_usd",
    "reserved_usd",
    "remaining_usd"
  ],
  "properties": {
    "contract": {
      "$ref": "urn:table-manners:core:result#/$defs/version"
    },
    "tool": {
      "$ref": "urn:table-manners:core:result#/$defs/tool"
    },
    "id": {
      "$ref": "urn:table-manners:core:run-ref#/$defs/session_id"
    },
    "started": {
      "type": "string",
      "format": "date-time"
    },
    "budget_usd": {
      "type": [
        "number",
        "null"
      ],
      "minimum": 0,
      "description": "The session budget; null when uncapped."
    },
    "spent_usd": {
      "type": "number",
      "minimum": 0,
      "description": "Settled spend, unresolved_usd included."
    },
    "unresolved_usd": {
      "type": "number",
      "minimum": 0,
      "description": "The part of spent_usd no provider answer settled: an upper bound."
    },
    "reserved_usd": {
      "type": "number",
      "minimum": 0,
      "description": "Worst cases held by runs still going."
    },
    "remaining_usd": {
      "type": [
        "number",
        "null"
      ],
      "minimum": 0,
      "description": "max(0, budget_usd - spent_usd - reserved_usd); null exactly when budget_usd is."
    }
  },
  "if": {
    "properties": {
      "budget_usd": {
        "type": "null"
      }
    }
  },
  "then": {
    "properties": {
      "remaining_usd": {
        "type": "null"
      }
    }
  },
  "else": {
    "properties": {
      "remaining_usd": {
        "type": "number"
      }
    }
  }
}

urn:table-manners:images:image-in.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:table-manners:images:image-in",
  "title": "Image in (CONTRACT.md 10.1)",
  "description": "An image given to an action's slot, by absolute path (local transports only) or inline, with an optional expected reference.",
  "oneOf": [
    {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "path"
      ],
      "properties": {
        "path": {
          "type": "string",
          "minLength": 1
        },
        "expect": {
          "$ref": "urn:table-manners:images:image-reference"
        }
      }
    },
    {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "inline"
      ],
      "properties": {
        "inline": {
          "$ref": "#/$defs/inline"
        },
        "expect": {
          "$ref": "urn:table-manners:images:image-reference"
        }
      }
    }
  ],
  "$defs": {
    "inline": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "media_type",
        "data"
      ],
      "properties": {
        "media_type": {
          "type": "string",
          "pattern": "^image/[a-z0-9.+-]+$"
        },
        "data": {
          "type": "string",
          "contentEncoding": "base64"
        }
      }
    }
  }
}

urn:table-manners:images:image-out.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:table-manners:images:image-out",
  "title": "Image out (CONTRACT.md 10.2)",
  "description": "An image a tool returns: its role, its reference and exactly one locator.",
  "type": "object",
  "required": [
    "role",
    "image"
  ],
  "properties": {
    "role": {
      "type": "string",
      "pattern": "^[a-z0-9][a-z0-9_-]*$"
    },
    "image": {
      "$ref": "urn:table-manners:images:image-reference"
    },
    "path": {
      "type": "string",
      "minLength": 1
    },
    "inline": {
      "$ref": "urn:table-manners:images:image-in#/$defs/inline"
    },
    "resource": {
      "type": "string",
      "pattern": "^[a-z][a-z0-9+.-]*://"
    }
  },
  "additionalProperties": false,
  "oneOf": [
    {
      "required": [
        "path"
      ]
    },
    {
      "required": [
        "inline"
      ]
    },
    {
      "required": [
        "resource"
      ]
    }
  ]
}

urn:table-manners:images:image-reference.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:table-manners:images:image-reference",
  "title": "Image reference (CONTRACT.md 8)",
  "description": "How a tool names an image to another tool: the file's digest and dimensions, its projection and topology.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "file_sha256",
    "width",
    "height",
    "projection",
    "topology"
  ],
  "properties": {
    "file_sha256": {
      "$ref": "#/$defs/sha256",
      "description": "SHA-256 of the file's bytes; the enforced check (2.1)."
    },
    "width": {
      "type": "integer",
      "minimum": 1,
      "description": "Pixels as stored, EXIF orientation not applied."
    },
    "height": {
      "type": "integer",
      "minimum": 1
    },
    "projection": {
      "enum": [
        "flat",
        "equirectangular"
      ]
    },
    "topology": {
      "enum": [
        "bounded",
        "wrap"
      ],
      "description": "wrap: x = 0 and x = 1 are the same edge."
    },
    "pixel_sha256": {
      "$ref": "#/$defs/sha256",
      "description": "The canonical pixel digest (2.2); a convenience, never an error when it differs."
    }
  },
  "if": {
    "properties": {
      "projection": {
        "const": "equirectangular"
      }
    }
  },
  "then": {
    "properties": {
      "topology": {
        "const": "wrap"
      }
    }
  },
  "$defs": {
    "sha256": {
      "type": "string",
      "pattern": "^[0-9a-f]{64}$"
    }
  }
}

urn:table-manners:images:location.text:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "urn:table-manners:images:location",
  "title": "Location (CONTRACT.md 9)",
  "description": "Where something is, on the original image, in fractions of its width and height measured at pixel edges.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "image",
    "kind",
    "parts",
    "straddles_wrap"
  ],
  "properties": {
    "image": {
      "$ref": "urn:table-manners:images:image-reference"
    },
    "kind": {
      "enum": [
        "bbox",
        "polygon",
        "line",
        "stroke",
        "mask",
        "whole_image",
        "absent",
        "view"
      ]
    },
    "parts": {
      "type": "array"
    },
    "straddles_wrap": {
      "type": "boolean",
      "description": "True when one shape was split at the wrap edge into several parts."
    },
    "label": {
      "type": "string"
    },
    "disposition": {
      "$ref": "#/$defs/word"
    },
    "confidence": {
      "$ref": "#/$defs/word"
    },
    "evidence": {
      "$ref": "#/$defs/word"
    },
    "score": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "A measured number, never comparable across tools or score kinds."
    },
    "score_kind": {
      "$ref": "#/$defs/word"
    },
    "reason": {
      "type": "string",
      "minLength": 1
    },
    "source": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "tool",
        "version"
      ],
      "properties": {
        "tool": {
          "type": "string",
          "minLength": 1
        },
        "version": {
          "type": "string",
          "minLength": 1
        },
        "run": {
          "type": "string",
          "minLength": 1
        },
        "item": {
          "type": "string",
          "minLength": 1
        }
      }
    }
  },
  "dependentRequired": {
    "score": [
      "score_kind"
    ],
    "score_kind": [
      "score"
    ]
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "kind": {
            "const": "bbox"
          }
        }
      },
      "then": {
        "properties": {
          "parts": {
            "minItems": 1,
            "items": {
              "$ref": "#/$defs/bbox_part"
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "const": "polygon"
          }
        }
      },
      "then": {
        "properties": {
          "parts": {
            "minItems": 1,
            "items": {
              "$ref": "#/$defs/polygon_part"
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "const": "line"
          }
        }
      },
      "then": {
        "properties": {
          "parts": {
            "minItems": 1,
            "items": {
              "$ref": "#/$defs/line_part"
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "const": "stroke"
          }
        }
      },
      "then": {
        "properties": {
          "parts": {
            "minItems": 1,
            "items": {
              "$ref": "#/$defs/stroke_part"
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "const": "mask"
          }
        }
      },
      "then": {
        "properties": {
          "parts": {
            "minItems": 1,
            "maxItems": 1,
            "items": {
              "$ref": "#/$defs/mask_part"
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "enum": [
              "whole_image",
              "absent"
            ]
          }
        }
      },
      "then": {
        "properties": {
          "parts": {
            "maxItems": 0
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "const": "absent"
          }
        }
      },
      "then": {
        "required": [
          "reason"
        ]
      }
    },
    {
      "if": {
        "properties": {
          "kind": {
            "const": "view"
          }
        }
      },
      "then": {
        "properties": {
          "parts": {
            "minItems": 1,
            "maxItems": 1,
            "items": {
              "$ref": "#/$defs/view_part"
            }
          },
          "image": {
            "properties": {
              "projection": {
                "const": "equirectangular"
              }
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "straddles_wrap": {
            "const": true
          }
        }
      },
      "then": {
        "properties": {
          "parts": {
            "minItems": 2
          },
          "image": {
            "properties": {
              "topology": {
                "const": "wrap"
              }
            }
          }
        }
      }
    }
  ],
  "$defs": {
    "word": {
      "type": "string",
      "pattern": "^[a-z0-9][a-z0-9_-]*$"
    },
    "fraction": {
      "type": "number",
      "minimum": 0,
      "maximum": 1
    },
    "point": {
      "type": "array",
      "prefixItems": [
        {
          "$ref": "#/$defs/fraction"
        },
        {
          "$ref": "#/$defs/fraction"
        }
      ],
      "items": false,
      "minItems": 2
    },
    "length_px": {
      "type": "number",
      "exclusiveMinimum": 0
    },
    "bbox_part": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "bbox"
      ],
      "properties": {
        "bbox": {
          "type": "array",
          "description": "[x0, y0, x1, y1] with x0 < x1 and y0 < y1.",
          "items": {
            "$ref": "#/$defs/fraction"
          },
          "minItems": 4,
          "maxItems": 4
        }
      }
    },
    "polygon_part": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "polygon"
      ],
      "properties": {
        "polygon": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/point"
          },
          "minItems": 3,
          "maxItems": 256
        }
      }
    },
    "line_part": {
      "oneOf": [
        {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "column",
            "width_px"
          ],
          "properties": {
            "column": {
              "$ref": "#/$defs/fraction"
            },
            "width_px": {
              "$ref": "#/$defs/length_px"
            }
          }
        },
        {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "path",
            "width_px"
          ],
          "properties": {
            "path": {
              "type": "array",
              "items": {
                "$ref": "#/$defs/point"
              },
              "minItems": 2,
              "maxItems": 256
            },
            "width_px": {
              "$ref": "#/$defs/length_px"
            }
          }
        }
      ]
    },
    "stroke_part": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "path",
        "radius_px"
      ],
      "properties": {
        "path": {
          "type": "array",
          "items": {
            "$ref": "#/$defs/point"
          },
          "minItems": 2,
          "maxItems": 256
        },
        "radius_px": {
          "$ref": "#/$defs/length_px"
        }
      }
    },
    "mask_part": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "mask"
      ],
      "properties": {
        "mask": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "image",
            "threshold"
          ],
          "description": "A greyscale 8-bit rendering at the located image's width and height; pixels at or above threshold are inside.",
          "properties": {
            "image": {
              "$ref": "urn:table-manners:images:image-reference"
            },
            "threshold": {
              "type": "integer",
              "minimum": 1,
              "maximum": 255
            }
          }
        }
      }
    },
    "view_part": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "yaw",
        "pitch",
        "fov"
      ],
      "description": "Input only. yaw 0 is the centre column, increasing to the right; pitch 0 the horizon, increasing upward; fov the horizontal field of a square view.",
      "properties": {
        "yaw": {
          "type": "number",
          "minimum": -180,
          "maximum": 180
        },
        "pitch": {
          "type": "number",
          "minimum": -90,
          "maximum": 90
        },
        "fov": {
          "type": "number",
          "minimum": 10,
          "maximum": 120
        }
      }
    }
  }
}
